  `Link_to_Functionality_Basis` varchar(255) DEFAULT NULL,
  `Usage_and_Dosage` text,
  `Basis_for_Usage_and_Dosage` varchar(255) DEFAULT NULL,
  `Link_to_Usage_and_Dosage` varchar(255) DEFAULT NULL,
  `Virulence` text,
  `Toxicity_Mechanism` text,
  `Pathological_Examination` text,
  `Crowd_Taboo` text,
  `Symptom_Contraindications` text,
  `ADR` text,
