CREATE TABLE `molecular_info` (
  `RecordNumber` bigint DEFAULT NULL,
  `RecordTitle` varchar(255) DEFAULT NULL,
  `Record Description?¨Ontology Summary??` text,
  `FDA Pharmacology Summary` text,
