  `Molecular Weight` double DEFAULT NULL,
  `XLogP3` double DEFAULT NULL,
  `Hydrogen Bond Donor Count` bigint DEFAULT NULL,
  `Hydrogen Bond Acceptor Count` bigint DEFAULT NULL,
  `Rotatable Bond Count` bigint DEFAULT NULL,
  `Heavy Atom Count` bigint DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
